import au.com.dius.pact.consumer.dsl.PactDslJsonBody;
import au.com.dius.pact.consumer.dsl.PactDslWithProvider;
import au.com.dius.pact.consumer.junit5.PactConsumerTestExt;
import au.com.dius.pact.consumer.junit5.PactTestFor;
import au.com.dius.pact.core.model.RequestResponsePact;
import au.com.dius.pact.core.model.annotations.Pact;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;

@ExtendWith(PactConsumerTestExt.class)
@PactTestFor(providerName = "UserAccountProvider", port = "8080")
public class UserAccountConsumerContractTest {

    @Pact(consumer = "BillingServiceConsumer")
    public RequestResponsePact createPact(PactDslWithProvider builder) {
        PactDslJsonBody responseBody = new PactDslJsonBody()
            ."uuid"("id", "123e4567-e89b-12d3-a456-426614174000")
            ."string"("username", "johndoe")
            ."boolean"("active", true);

        return builder
            .given("user 123 exists")
            .path("/api/users/123")
            .method("GET")
            .willRespondWith()
            .status(200)
            .body(responseBody)
            .toPact();
    }

    @Test
    public void testGetUserAccount(PactDslWithProvider builder) {
        // Execute actual HTTP client call against the local Pact mock server
        UserAccountClient client = new UserAccountClient("http://localhost:8080");
        UserAccountDto account = client.getUser("123");
        Assertions.assertNotNull(account);
        Assertions.assertEquals("johndoe", account.getUsername());
    }
}
